use std::{path::{Path,PathBuf}, time::Instant};
use asr_audio::{CanonicalAudio,decode_wav};
use asr_metrics::{character_error_rate,normalize_text,word_error_rate};
use asr_runtime::{OrtCtcSession,ProviderKind,SessionConfig,metadata::model_metadata::CandidateMetadata};
use crate::{benchmark::{SampleAggregate,build_benchmark}, config::load_revision_hashes, decoding::ctc::{Vocabulary,greedy_ctc_ids}, manifest::load_resolved_manifest, run_context::build_run_context, writer::{ensure_dir,write_json,write_jsonl}, Result};

#[derive(Debug,Clone)] pub struct EvaluateOptions { pub provider:ProviderKind,pub model:PathBuf,pub candidate_dir:PathBuf,pub candidate_id:Option<String>,pub vocabulary:PathBuf,pub resolved_manifest:PathBuf,pub evaluation:String,pub model_id:String,pub revisions:PathBuf,pub output:PathBuf }

pub fn evaluate(options:EvaluateOptions)->Result<serde_json::Value>{
 let manifest=load_resolved_manifest(&options.resolved_manifest)?; let revisions=load_revision_hashes(&options.revisions)?; let metadata=CandidateMetadata::load(&options.candidate_dir)?; let mut session=OrtCtcSession::create(SessionConfig::new(&options.model,options.provider),metadata.runtime_contract.clone())?; let vocab=Vocabulary::load(&options.vocabulary)?; ensure_dir(&options.output)?; let context=build_run_context(&options.model,&options.model_id,options.candidate_id.as_deref(),options.provider,&options.evaluation,&revisions)?; let run_id=context["run_id"].as_str().unwrap().to_owned(); let mut results=Vec::with_capacity(manifest.samples.len()); let mut agg=SampleAggregate::default();
 for sample in &manifest.samples { let started=Instant::now(); let result=(||->Result<serde_json::Value>{ let path=Path::new(sample.audio_path.as_deref().unwrap()); let decode_started=Instant::now(); let decoded=decode_wav(path)?; let decode_ms=decode_started.elapsed().as_secs_f64()*1000.0; let resample_started=Instant::now(); let canonical=CanonicalAudio::from_decoded(decoded)?; let resample_ms=resample_started.elapsed().as_secs_f64()*1000.0; let inference=session.run_waveform(&canonical.waveform)?; let decode_token_started=Instant::now(); let ids=greedy_ctc_ids(&inference.logits.values,&inference.logits.shape,metadata.runtime_contract.blank_id)?; let decoder_ms=decode_token_started.elapsed().as_secs_f64()*1000.0; let post=Instant::now(); let text=vocab.decode(&ids)?; let normalized=normalize_text(&text); let post_ms=post.elapsed().as_secs_f64()*1000.0; let total_ms=started.elapsed().as_secs_f64()*1000.0; let cer=character_error_rate(&sample.transcription,&text); let wer=word_error_rate(&sample.transcription,&text); agg.add_success(canonical.duration_sec(),cer,wer,total_ms,inference.inference_ms); Ok(serde_json::json!({"schema_version":1,"run_id":run_id,"sample":{"id":sample.id,"dataset_id":sample.dataset_id,"dataset_repo_id":sample.dataset_repo_id,"dataset_revision":sample.dataset_revision,"subset":sample.subset,"split":sample.split,"index":sample.row_index,"audio_sha256":sample.audio_sha256,"audio_duration_sec":canonical.duration_sec(),"sample_rate_hz":canonical.sample_rate_hz,"reference_text":sample.transcription},"execution":{"runtime":"rust","backend":"onnxruntime","provider_id":options.provider.to_string(),"decoder":"ctc","batch_size":1},"output":{"text":text,"normalized_text":normalized,"tokens":ids,"token_count":ids.len()},"quality":{"cer":cer,"wer":wer},"timing":{"load_ms":null,"session_creation_ms":null,"audio_decode_ms":decode_ms,"resample_ms":resample_ms,"frontend_ms":null,"encoder_ms":null,"decoder_ms":decoder_ms,"postprocess_ms":post_ms,"inference_ms":inference.inference_ms,"total_ms":total_ms,"rtf":total_ms/1000.0/canonical.duration_sec()},"memory":{"peak_ram_mb":asr_metrics::current_process_memory_mb(),"peak_device_memory_mb":null},"parity":{"reference_run_id":null,"text_match":null,"token_match":null,"numeric":{"frontend":{"compared":false,"passed":null,"max_abs_error":null,"mean_abs_error":null,"relative_l2":null},"encoder":{"compared":false,"passed":null,"max_abs_error":null,"mean_abs_error":null,"relative_l2":null},"logits":{"compared":false,"passed":null,"max_abs_error":null,"mean_abs_error":null,"relative_l2":null}}},"provider":{"requested":options.provider.to_string(),"registered":true,"used":true,"fallback_detected":null,"fallback_only":null,"assigned_nodes":null,"fallback_nodes":null},"status":"success","errors":[]})) })(); match result {Ok(v)=>results.push(v),Err(e)=>{agg.add_failure(); results.push(serde_json::json!({"schema_version":1,"run_id":run_id,"sample":{"id":sample.id,"dataset_id":sample.dataset_id,"dataset_repo_id":sample.dataset_repo_id,"dataset_revision":sample.dataset_revision,"subset":sample.subset,"split":sample.split,"index":sample.row_index,"audio_sha256":sample.audio_sha256,"audio_duration_sec":sample.duration_sec,"sample_rate_hz":sample.sample_rate_hz.unwrap_or(16000),"reference_text":sample.transcription},"execution":{"runtime":"rust","backend":"onnxruntime","provider_id":options.provider.to_string(),"decoder":"ctc","batch_size":1},"output":{"text":"","normalized_text":"","tokens":[],"token_count":0},"quality":{"cer":null,"wer":null},"timing":{"load_ms":null,"session_creation_ms":null,"audio_decode_ms":null,"resample_ms":null,"frontend_ms":null,"encoder_ms":null,"decoder_ms":null,"postprocess_ms":null,"inference_ms":null,"total_ms":started.elapsed().as_secs_f64()*1000.0,"rtf":null},"memory":{"peak_ram_mb":null,"peak_device_memory_mb":null},"parity":{"reference_run_id":null,"text_match":null,"token_match":null,"numeric":{"frontend":{"compared":false,"passed":null,"max_abs_error":null,"mean_abs_error":null,"relative_l2":null},"encoder":{"compared":false,"passed":null,"max_abs_error":null,"mean_abs_error":null,"relative_l2":null},"logits":{"compared":false,"passed":null,"max_abs_error":null,"mean_abs_error":null,"relative_l2":null}}},"provider":{"requested":options.provider.to_string(),"registered":true,"used":null,"fallback_detected":null,"fallback_only":null,"assigned_nodes":null,"fallback_nodes":null},"status":"failed","errors":[{"code":"SAMPLE_EVALUATION_FAILED","stage":"inference","message":e.to_string(),"fatal":true}]}));}}
 }
 write_json(&options.output.join("run-context.json"),&context)?; write_jsonl(&options.output.join("samples.jsonl"),&results)?; let benchmark=build_benchmark(&context,options.candidate_id.as_deref(),&options.model_id,&options.evaluation,&manifest.manifest_path,manifest.expected_sample_count,&options.provider.to_string(),options.provider.ort_name(),&agg); write_json(&options.output.join("metrics.json"),&benchmark)?; Ok(benchmark)
}
